-- =====================================================================
-- Flyway 迁移：全库 collation 统一为 utf8mb4_0900_ai_ci（清偿 D-095 遗留债务）
-- 日期：2026-08-16
-- 背景：
--   D-095 事故暴露全库 290 张表 4 种 collation 并存：
--   0900_ai_ci 216（主流）/ unicode_ci 49 / general_ci 14 / bin 11。
--   跨派字符串 JOIN 报 ERROR 1267（MyBatis 摘要为 setting parameters）。
--   本迁移将 74 张少数派表全部 CONVERT 对齐主流。
-- 风险评估（已完成，全部通过）：
--   1. 74 张表在 Java 代码中零跨表 JOIN 引用（不影响现有查询）
--   2. 18 个唯一索引 + 4 个 varchar 主键逐一 0900 规则撞键预检 = 0 冲突
--   3. 全库无列级 collation 与表默认不一致的隐藏分离列
--   4. bin→0900 语义变化（大小写敏感→不敏感）：涉及表均无大小写敏感
--      唯一约束依赖，查询只会变宽松不会报错
-- 注意：
--   - t_ai_job_run_log（49万行）CONVERT 需数秒，生产部署留意窗口
--   - 脚本幂等可重复执行：已是 0900 或表不存在时自动跳过（NULL 判断走 SELECT 1）
-- =====================================================================

-- ---------------------------------------------------------------------
-- A. utf8mb4_bin 派 11 张（AI agent 辅助表 + 订单备注/发货）
-- ---------------------------------------------------------------------
SET @sql = IF((SELECT TABLE_COLLATION FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='t_advisor_feedback') != 'utf8mb4_0900_ai_ci', 'ALTER TABLE t_advisor_feedback CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
