-- ---------------------------------------------------------------------
-- D. 库默认 collation 对齐（老环境防复发：未显式指定 collation 的后续动态建表继承 0900）
-- ---------------------------------------------------------------------
SET @sql = IF((SELECT DEFAULT_COLLATION_NAME FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = DATABASE()) != 'utf8mb4_0900_ai_ci',
  CONCAT('ALTER DATABASE ', DATABASE(), ' COLLATE utf8mb4_0900_ai_ci'), 'SELECT 1');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

-- ---------------------------------------------------------------------
-- E. 迁移后校验：剩余非 0900 表数（预期为 0）
-- ---------------------------------------------------------------------
SELECT TABLE_COLLATION, COUNT(*) AS remaining FROM INFORMATION_SCHEMA.TABLES
WHERE TABLE_SCHEMA = DATABASE() AND TABLE_TYPE='BASE TABLE' AND TABLE_COLLATION != 'utf8mb4_0900_ai_ci'
GROUP BY TABLE_COLLATION;
